import numpy as np
from flip_augmentation import update_image_and_anno

class Test_FlipAugmentationUpdateImageAndAnno:

    @pytest.mark.valid
    @pytest.mark.smoke
    def test_horizontal_flip_logic(self):
        # Arrange
        test_image_1 = np.zeros((100, 100, 3), dtype=np.uint8)
        test_image_1[::2, ::2] = 255  # checkerboard pattern

        test_image_2 = np.zeros((100, 100, 3), dtype=np.uint8)
        test_image_2[1::2, 1::2] = 255  # checkerboard pattern

        img_list = ['test_image_1.png', 'test_image_2.png']
        anno_list = [
            [[0, 0.5, 0.5, 0.1, 0.1]],
            [[0, 0.6, 0.6, 0.1, 0.1]]
        ]

        # Mock cv2.imread to return the test images
        def mock_imread(path):
            if path == 'test_image_1.png':
                return test_image_1
            elif path == 'test_image_2.png':
                return test_image_2

        cv2.imread = mock_imread

        # Act
        new_imgs_list, new_annos_lists, path_list = update_image_and_anno(img_list, anno_list, flip_type=1)

        # Assert
        assert len(new_imgs_list) == 2
        assert len(new_annos_lists) == 2
        assert path_list == ['test_image_1.png', 'test_image_2.png']

        # Check the flipped images
        assert np.array_equal(new_imgs_list[0], cv2.flip(test_image_1, 1))
        assert np.array_equal(new_imgs_list[1], cv2.flip(test_image_2, 1))

        # Check the updated annotations
        expected_annos = [
            [[0, 0.5, 0.5, 0.1, 0.1]],
            [[0, 0.4, 0.6, 0.1, 0.1]]
        ]
        assert new_annos_lists == expected_annos

